const fs=require('fs'),vm=require('vm'),assert=require('assert');const input=JSON.parse(fs.readFileSync(0,'utf8'));let callback;
const server={player:{extra:{prestigeBattle:{practiceTimes:4}}}};
function load(name){const start=input.source.indexOf(name+': [ function('),end=input.source.indexOf('cc._RF.pop();',start);assert(start>=0);const source=input.source.slice(start,end)+'cc._RF.pop();\n}';const begin=source.indexOf('function(');const mod={exports:{}};vm.runInNewContext('('+source.slice(begin)+')',{cc:{_RF:{push(){},pop(){}}}})(dep=>dep==='socket'?{request:(route,args,cb)=>{callback=cb;}}:dep==='serverMain'?server:(()=>{throw Error(dep)})(),mod,mod.exports);return mod.exports;}
const handler=load('prestigeBattleHandler');handler.dissolveTeam(1,()=>{server.player.extra.prestigeBattle.practiceTimes--;});callback({_temp:{canonicalState:input.state}});assert.deepEqual(server.player.extra.prestigeBattle,input.state);process.stdout.write(JSON.stringify({canonical:true}));
